/* Binary assets linked into the ELF; generated by tools/build_*.py. The
   music is not among them: it streams from the disc (disc/music.adp). */
    .section .rodata
    .balign 32
    .global _dk_textures_pak
_dk_textures_pak:
    .incbin "assets/generated/textures.pak"

    .balign 32
    .global _dk_sfx_pak
_dk_sfx_pak:
    .incbin "assets/generated/sfx.pak"
